-- T08 costs and settlements are distinct immutable sources. Reports use ledger-line grain.
grant create on schema api,app_private,finance_private to git_tutor_commands;
create table finance_private.expenses(id uuid primary key default gen_random_uuid(),category text not null check(category in('teaching','marketing','software','rent','administration','other')),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),currency text not null check(currency='EGP'),incurred_at timestamptz not null,description text not null,evidence_file_id uuid not null references app_private.files(id),ledger_transaction_id uuid not null references finance_private.ledger_transactions(id),actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null unique,created_at timestamptz not null default now());
create table finance_private.expense_accounts(expense_id uuid primary key references finance_private.expenses(id),version integer not null default 1);
create table finance_private.expense_settlements(id uuid primary key default gen_random_uuid(),expense_id uuid not null references finance_private.expenses(id),amount_minor bigint not null check(amount_minor between 1 and 9007199254740991),receiving_account_id uuid not null references finance_private.receiving_accounts(id),external_reference text not null,settled_at timestamptz not null,evidence_file_id uuid not null references app_private.files(id),ledger_transaction_id uuid not null references finance_private.ledger_transactions(id),actor_account_id uuid not null references app_private.accounts(id),command_id uuid not null unique,created_at timestamptz not null default now(),unique(receiving_account_id,external_reference));
create table finance_private.outgoing_cash_references(receiving_account_id uuid not null references finance_private.receiving_accounts(id),external_reference text not null,source_type text not null check(source_type in('expense','payout')),source_id uuid not null,created_at timestamptz not null default now(),primary key(receiving_account_id,external_reference));
create table finance_private.cash_reconciliations(id uuid primary key default gen_random_uuid(),receiving_account_id uuid not null references finance_private.receiving_accounts(id),balance_at timestamptz not null,posted_as_of timestamptz not null,observed_balance_minor bigint not null,ledger_balance_minor bigint not null,difference_minor bigint not null,evidence_file_id uuid not null references app_private.files(id),reason text not null,owner_account_id uuid not null references app_private.accounts(id),command_id uuid not null unique,created_at timestamptz not null default now());
create index ledger_transaction_period on finance_private.ledger_transactions(effective_at,recorded_at,id);
create index expense_settlement_source on finance_private.expense_settlements(expense_id);

create function finance_private.finance_safe_total(p_value numeric)returns bigint language plpgsql immutable set search_path='' as $$begin if p_value is null or p_value<>trunc(p_value)or p_value not between -9007199254740991 and 9007199254740991 then raise exception'AMOUNT_OUT_OF_RANGE';end if;return p_value::bigint;end$$;
create function finance_private.finance_report_range(p_from date,p_to date,p_as_of timestamptz)returns table(period_start timestamptz,period_end timestamptz,recorded_cutoff timestamptz)language plpgsql stable set search_path='' as $$begin
 if p_from is null or p_to is null or p_as_of is null or not isfinite(p_from)or not isfinite(p_to)or not isfinite(p_as_of)or p_from<date'2000-01-01'or p_to>date'9999-12-30'or p_to<p_from or p_as_of>now()+interval'5 seconds'then raise exception'INVALID_TIME';end if;
 return query select p_from::timestamp at time zone'Africa/Cairo',(p_to+1)::timestamp at time zone'Africa/Cairo',p_as_of;
end$$;

alter function app_private.file_resolve_target(uuid,text,text,uuid)rename to file_resolve_target_pre_finance;
create function app_private.file_resolve_target(p_actor uuid,p_purpose text,p_action text,p_target uuid)returns jsonb language plpgsql security definer set search_path='' as $$
declare internal text;parent text;begin
 if p_purpose='review_evidence'and p_action in('record_expense','record_expense_settlement','cash_reconciliation')then
  perform app_private.require_role(p_actor,'admin');
  if p_action='record_expense'then if p_target is not null then raise exception'VALIDATION_ERROR';end if;internal:='expense_evidence';parent:='expense';
  elsif p_action='record_expense_settlement'then if not exists(select 1 from finance_private.expenses where id=p_target)then raise exception'NOT_FOUND';end if;internal:='expense_settlement';parent:='expense';
  else if not exists(select 1 from finance_private.receiving_accounts where id=p_target)then raise exception'NOT_FOUND';end if;internal:='cash_reconciliation';parent:='receiving_account';end if;
  return jsonb_build_object('internal_purpose',internal,'parent_type',parent,'parent_id',p_target,'learner_id',null,'charge_id',null);
 end if;
 return app_private.file_resolve_target_pre_finance(p_actor,p_purpose,p_action,p_target);
end$$;

create function api.record_expense(p_category text,p_amount_minor bigint,p_currency text,p_incurred_at timestamptz,p_description text,p_evidence_file_id uuid,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();ctx jsonb;expense uuid:=gen_random_uuid();ledger uuid;begin
 perform app_private.require_role(actor,'admin');perform app_private.payment_assert_file(p_evidence_file_id,'expense_evidence','expense',null,actor);
 ctx:=app_private.booking_begin(actor,'record_expense',jsonb_build_object('category',p_category,'amount_minor',p_amount_minor,'currency',p_currency,'incurred_at',p_incurred_at,'description',p_description,'evidence_file_id',p_evidence_file_id),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if p_category is null or p_category not in('teaching','marketing','software','rent','administration','other')or p_amount_minor is null or p_amount_minor not between 1 and 9007199254740991 or p_currency is distinct from'EGP'or p_description is null or length(btrim(p_description))not between 1 and 2000 then raise exception'VALIDATION_ERROR';end if;
 if p_incurred_at is null or not isfinite(p_incurred_at)or p_incurred_at>now()or p_incurred_at<timestamptz'2000-01-01Z'then raise exception'INVALID_TIME';end if;
 ledger:=finance_private.finance_post_balanced('expense:'||expense,'expense',expense,'EGP',p_incurred_at,jsonb_build_array(jsonb_build_object('account_code','operating_expense','signed_minor',p_amount_minor),jsonb_build_object('account_code','expense_payable','signed_minor',-p_amount_minor)),ctx);
 insert into finance_private.expenses(id,category,amount_minor,currency,incurred_at,description,evidence_file_id,ledger_transaction_id,actor_account_id,command_id)values(expense,p_category,p_amount_minor,'EGP',p_incurred_at,btrim(p_description),p_evidence_file_id,ledger,actor,(ctx->>'command_id')::uuid);insert into finance_private.expense_accounts(expense_id)values(expense);
 return app_private.booking_finish(ctx,expense,1,jsonb_build_object('expense_id',expense,'payable_minor',p_amount_minor),'expense_recorded',jsonb_build_object('expense_id',expense));
end$$;
create function api.record_expense_settlement(p_expense_id uuid,p_amount_minor bigint,p_receiving_account_id uuid,p_external_reference text,p_settled_at timestamptz,p_evidence_file_id uuid,p_expected_version integer,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();ctx jsonb;e finance_private.expenses%rowtype;v integer;remaining bigint;settlement uuid:=gen_random_uuid();ledger uuid;begin
 perform app_private.require_role(actor,'admin');select * into e from finance_private.expenses where id=p_expense_id;if e.id is null then raise exception'NOT_FOUND';end if;perform app_private.payment_assert_file(p_evidence_file_id,'expense_settlement','expense',e.id,actor);
 ctx:=app_private.booking_begin(actor,'record_expense_settlement',jsonb_build_object('expense_id',p_expense_id,'amount_minor',p_amount_minor,'receiving_account_id',p_receiving_account_id,'external_reference',p_external_reference,'settled_at',p_settled_at,'evidence_file_id',p_evidence_file_id,'expected_version',p_expected_version),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 if p_external_reference is null or length(btrim(p_external_reference))not between 1 and 200 or p_external_reference<>btrim(p_external_reference)then raise exception'VALIDATION_ERROR';end if;
 if p_settled_at is null or not isfinite(p_settled_at)or p_settled_at>now()or p_settled_at<e.incurred_at then raise exception'INVALID_TIME';end if;
 if not exists(select 1 from finance_private.receiving_accounts a join finance_private.receiving_account_versions v on v.id=a.current_version_id where a.id=p_receiving_account_id and v.approved_at is not null)then raise exception'DESTINATION_UNVERIFIED';end if;
 perform pg_advisory_xact_lock(hashtextextended('outgoing-cash:'||p_receiving_account_id||':'||p_external_reference,0));select version into v from finance_private.expense_accounts where expense_id=e.id for update;if v is distinct from p_expected_version then raise exception'VERSION_CONFLICT';end if;
 select e.amount_minor-coalesce(sum(s.amount_minor),0)into remaining from finance_private.expense_settlements s where s.expense_id=e.id;if p_amount_minor is null or p_amount_minor<1 or p_amount_minor>remaining then raise exception'AMOUNT_OUT_OF_RANGE';end if;
 if exists(select 1 from finance_private.outgoing_cash_references where receiving_account_id=p_receiving_account_id and external_reference=p_external_reference)then raise exception'STATE_CONFLICT';end if;
 insert into finance_private.outgoing_cash_references(receiving_account_id,external_reference,source_type,source_id)values(p_receiving_account_id,p_external_reference,'expense',settlement);
 ledger:=finance_private.finance_post_balanced('expense-settlement:'||settlement,'expense_settlement',settlement,'EGP',p_settled_at,jsonb_build_array(jsonb_build_object('account_code','expense_payable','signed_minor',p_amount_minor),jsonb_build_object('account_code','channel_cash','signed_minor',-p_amount_minor,'receiving_account_id',p_receiving_account_id)),ctx);
 insert into finance_private.expense_settlements(id,expense_id,amount_minor,receiving_account_id,external_reference,settled_at,evidence_file_id,ledger_transaction_id,actor_account_id,command_id)values(settlement,e.id,p_amount_minor,p_receiving_account_id,p_external_reference,p_settled_at,p_evidence_file_id,ledger,actor,(ctx->>'command_id')::uuid);update finance_private.expense_accounts set version=version+1 where expense_id=e.id returning version into v;
 return app_private.booking_finish(ctx,e.id,v,jsonb_build_object('settlement_id',settlement,'remaining_payable_minor',remaining-p_amount_minor),'expense_settled',jsonb_build_object('expense_id',e.id,'settlement_id',settlement));
end$$;
create function api.record_cash_reconciliation(p_receiving_account_id uuid,p_observed_balance_minor bigint,p_balance_at timestamptz,p_evidence_file_id uuid,p_reason text,p_idempotency_key text)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();ctx jsonb;rid uuid:=gen_random_uuid();balance bigint;difference bigint;begin
 perform app_private.require_role(actor,'admin');perform app_private.payment_assert_file(p_evidence_file_id,'cash_reconciliation','receiving_account',p_receiving_account_id,actor);if not exists(select 1 from finance_private.receiving_accounts where id=p_receiving_account_id)then raise exception'NOT_FOUND';end if;
 ctx:=app_private.booking_begin(actor,'record_cash_reconciliation',jsonb_build_object('receiving_account_id',p_receiving_account_id,'observed_balance_minor',p_observed_balance_minor,'balance_at',p_balance_at,'evidence_file_id',p_evidence_file_id,'reason',p_reason),p_idempotency_key);if ctx->'replay_result'<>'null'::jsonb then return ctx->'replay_result';end if;
 perform finance_private.finance_safe_total(p_observed_balance_minor);if p_reason is null or length(btrim(p_reason))not between 1 and 2000 then raise exception'VALIDATION_ERROR';end if;if p_balance_at is null or not isfinite(p_balance_at)or p_balance_at>now()then raise exception'INVALID_TIME';end if;
 select finance_private.finance_safe_total(coalesce(sum(l.signed_minor),0))into balance from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where l.account_code='channel_cash'and l.receiving_account_id=p_receiving_account_id and t.effective_at<=p_balance_at and t.recorded_at<=now();difference:=finance_private.finance_safe_total(p_observed_balance_minor::numeric-balance);
 insert into finance_private.cash_reconciliations(id,receiving_account_id,balance_at,posted_as_of,observed_balance_minor,ledger_balance_minor,difference_minor,evidence_file_id,reason,owner_account_id,command_id)values(rid,p_receiving_account_id,p_balance_at,now(),p_observed_balance_minor,balance,difference,p_evidence_file_id,btrim(p_reason),actor,(ctx->>'command_id')::uuid);
 return app_private.booking_finish(ctx,rid,1,jsonb_build_object('reconciliation_id',rid,'ledger_balance_minor',balance,'difference_minor',difference,'state',case when difference=0 then'matched'else'difference'end),'cash_reconciliation_recorded',jsonb_build_object('reconciliation_id',rid,'receiving_account_id',p_receiving_account_id));
end$$;

create function api.get_finance_summary(p_from date,p_to date,p_as_of timestamptz)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();bounds record;period jsonb;balances jsonb;balanced boolean;entries integer;begin
 perform app_private.require_role(actor,'admin');select * into bounds from finance_private.finance_report_range(p_from,p_to,p_as_of);
 with totals as(select l.account_code,sum(l.signed_minor)amount,coalesce(sum(l.signed_minor)filter(where l.signed_minor>0),0)inflow,coalesce(sum(-l.signed_minor)filter(where l.signed_minor<0),0)outflow from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where t.effective_at>=bounds.period_start and t.effective_at<bounds.period_end and t.recorded_at<=bounds.recorded_cutoff group by l.account_code),report_values as(select
 -coalesce((select amount from totals where account_code='tuition_revenue'),0)revenue,coalesce((select amount from totals where account_code='tutor_expense'),0)tutor,coalesce((select amount from totals where account_code='operating_expense'),0)operating,coalesce((select amount from totals where account_code='promotional_subsidy_expense'),0)subsidy,
 coalesce((select inflow from totals where account_code='channel_cash'),0)inflow,coalesce((select outflow from totals where account_code='channel_cash'),0)outflow,coalesce((select amount from totals where account_code='channel_cash'),0)cash)
 select jsonb_build_object('earned_revenue_minor',finance_private.finance_safe_total(revenue),'tutor_expense_minor',finance_private.finance_safe_total(tutor),'operating_expense_minor',finance_private.finance_safe_total(operating),'promotional_subsidy_minor',finance_private.finance_safe_total(subsidy),'operating_profit_minor',finance_private.finance_safe_total(revenue-tutor-operating-subsidy),'cash_inflow_minor',finance_private.finance_safe_total(inflow),'cash_outflow_minor',finance_private.finance_safe_total(outflow),'net_cash_movement_minor',finance_private.finance_safe_total(cash))into period from report_values;
 with totals as(select l.account_code,sum(l.signed_minor)amount from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where t.effective_at<bounds.period_end and t.recorded_at<=bounds.recorded_cutoff group by l.account_code)
 select jsonb_build_object('cash_minor',finance_private.finance_safe_total(coalesce((select amount from totals where account_code='channel_cash'),0)),'receivable_minor',finance_private.finance_safe_total(coalesce((select amount from totals where account_code='receivable'),0)),
 'customer_credit_minor',finance_private.finance_safe_total(-coalesce((select amount from totals where account_code='unapplied_customer_funds'),0)),'deferred_tuition_minor',finance_private.finance_safe_total(-coalesce((select amount from totals where account_code='deferred_tuition'),0)),'package_obligation_minor',finance_private.finance_safe_total(-coalesce((select amount from totals where account_code='deferred_package_obligation'),0)),
 'tutor_payable_minor',finance_private.finance_safe_total(-coalesce((select amount from totals where account_code='tutor_payable'),0)),'expense_payable_minor',finance_private.finance_safe_total(-coalesce((select amount from totals where account_code='expense_payable'),0)))into balances;
 select coalesce(sum(l.signed_minor),0)=0,count(*)filter(where t.effective_at>=bounds.period_start)::integer into balanced,entries from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where t.effective_at<bounds.period_end and t.recorded_at<=bounds.recorded_cutoff;
 return jsonb_build_object('from',p_from,'to',p_to,'as_of',p_as_of,'currency','EGP','time_zone','Africa/Cairo','grain','ledger_line','period',period,'balances',balances,'ledger_balanced',balanced,'source_entry_count',entries);
end$$;
create function api.list_finance_entries(p_from date,p_to date,p_as_of timestamptz,p_account_codes text[]default'{}',p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();bounds record;items jsonb;lastid uuid;begin
 perform app_private.require_role(actor,'admin');select * into bounds from finance_private.finance_report_range(p_from,p_to,p_as_of);if p_limit not between 1 and 100 or p_account_codes is null or cardinality(p_account_codes)>11 or not p_account_codes<@array['channel_cash','receivable','unapplied_customer_funds','deferred_tuition','deferred_package_obligation','tuition_revenue','tutor_expense','tutor_payable','operating_expense','expense_payable','promotional_subsidy_expense']then raise exception'VALIDATION_ERROR';end if;
 if p_cursor is not null and not exists(select 1 from finance_private.ledger_lines where id=p_cursor)then raise exception'NOT_FOUND';end if;
 select coalesce(jsonb_agg(x.item order by x.recorded_at desc,x.id desc),'[]'::jsonb)into items from(select l.id,l.recorded_at,jsonb_build_object('line_id',l.id,'transaction_id',t.id,'source_type',t.source_type,'source_id',t.source_id,'account_code',l.account_code,'signed_minor',l.signed_minor,'currency',l.currency,'effective_at',t.effective_at,'recorded_at',t.recorded_at,'charge_id',l.charge_id,'enrollment_id',l.enrollment_id,'receiving_account_id',l.receiving_account_id)item from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where t.effective_at>=bounds.period_start and t.effective_at<bounds.period_end and t.recorded_at<=bounds.recorded_cutoff and(cardinality(p_account_codes)=0 or l.account_code=any(p_account_codes))and(p_cursor is null or(l.recorded_at,l.id)<(select c.recorded_at,c.id from finance_private.ledger_lines c where c.id=p_cursor))order by l.recorded_at desc,l.id desc limit p_limit)x;
 if jsonb_array_length(items)=p_limit then lastid:=(items->(p_limit-1)->>'line_id')::uuid;end if;return jsonb_build_object('items',items,'next_cursor',lastid);
end$$;
create function api.list_expenses(p_cursor uuid default null,p_limit integer default 25)returns jsonb language plpgsql security definer set search_path='' as $$
declare actor uuid:=app_private.require_actor();items jsonb;lastid uuid;begin
 perform app_private.require_role(actor,'admin');if p_limit not between 1 and 100 then raise exception'VALIDATION_ERROR';end if;if p_cursor is not null and not exists(select 1 from finance_private.expenses where id=p_cursor)then raise exception'NOT_FOUND';end if;
 select coalesce(jsonb_agg(x.item order by x.created_at desc,x.id desc),'[]'::jsonb)into items from(select e.id,e.created_at,jsonb_build_object('expense_id',e.id,'category',e.category,'amount_minor',e.amount_minor,'currency',e.currency,'incurred_at',e.incurred_at,'description',e.description,'evidence_file_id',e.evidence_file_id,'paid_minor',paid.amount,'payable_minor',e.amount_minor-paid.amount,'state',case when paid.amount=0 then'unpaid'when paid.amount=e.amount_minor then'paid'else'partially_paid'end,'version',a.version,'created_at',e.created_at)item from finance_private.expenses e join finance_private.expense_accounts a on a.expense_id=e.id cross join lateral(select coalesce(sum(s.amount_minor),0)::bigint amount from finance_private.expense_settlements s where s.expense_id=e.id)paid where(p_cursor is null or(e.created_at,e.id)<(select c.created_at,c.id from finance_private.expenses c where c.id=p_cursor))order by e.created_at desc,e.id desc limit p_limit)x;
 if jsonb_array_length(items)=p_limit then lastid:=(items->(p_limit-1)->>'expense_id')::uuid;end if;return jsonb_build_object('items',items,'next_cursor',lastid);
end$$;
create function api.list_finance_cash_accounts()returns jsonb language plpgsql security definer set search_path='' as $$declare actor uuid:=app_private.require_actor();items jsonb;begin
 perform app_private.require_role(actor,'admin');select coalesce(jsonb_agg(jsonb_build_object('receiving_account_id',a.id,'channel',a.channel,'label',a.channel||' · '||left(a.id::text,8),'enabled',a.enabled,'balance_minor',finance_private.finance_safe_total((select coalesce(sum(l.signed_minor),0)from finance_private.ledger_lines l join finance_private.ledger_transactions t on t.id=l.transaction_id where l.account_code='channel_cash'and l.receiving_account_id=a.id and t.effective_at<=now()and t.recorded_at<=now())),'last_reconciliation',(select jsonb_build_object('reconciliation_id',r.id,'balance_at',r.balance_at,'observed_balance_minor',r.observed_balance_minor,'ledger_balance_minor',r.ledger_balance_minor,'difference_minor',r.difference_minor,'state',case when r.difference_minor=0 then'matched'else'difference'end)from finance_private.cash_reconciliations r where r.receiving_account_id=a.id order by r.created_at desc,r.id desc limit 1))order by a.created_at desc,a.id desc),'[]'::jsonb)into items from finance_private.receiving_accounts a;return jsonb_build_object('items',items);
end$$;

do $$declare t record;f record;begin
 for t in select tablename from pg_tables where schemaname='finance_private'and tablename in('expenses','expense_accounts','expense_settlements','outgoing_cash_references','cash_reconciliations')loop
 execute format('alter table finance_private.%I enable row level security',t.tablename);execute format('create policy commands_access on finance_private.%I to git_tutor_commands using(true)with check(true)',t.tablename);execute format('revoke all on finance_private.%I from public,anon,authenticated,service_role,git_tutor_worker',t.tablename);execute format('grant select,insert on finance_private.%I to git_tutor_commands',t.tablename);
 if t.tablename='expense_accounts'then execute format('grant update on finance_private.%I to git_tutor_commands',t.tablename);else execute format('create trigger immutable_row before update or delete on finance_private.%I for each row execute function app_private.reject_immutable_change()',t.tablename);end if;end loop;
 for f in select p.oid::regprocedure::text signature,n.nspname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in('api','app_private','finance_private')and p.proname=any(array['finance_safe_total','finance_report_range','file_resolve_target','record_expense','record_expense_settlement','record_cash_reconciliation','get_finance_summary','list_finance_entries','list_expenses','list_finance_cash_accounts'])loop
 execute format('alter function %s owner to git_tutor_commands',f.signature);execute format('revoke all on function %s from public,anon,authenticated,service_role,git_tutor_worker',f.signature);if f.nspname='api'then execute format('grant execute on function %s to authenticated',f.signature);end if;end loop;end$$;
revoke create on schema api,app_private,finance_private from git_tutor_commands;
